import{_ as r,E as s,o,a as l,a6 as a,I as i}from"./chunks/framework.BNef1kRO.js";const b=JSON.parse('{"title":"商业视觉 Prompt 结构","description":"面向商业视觉项目的可复用提示词结构与检查方法。","frontmatter":{"title":"商业视觉 Prompt 结构","description":"面向商业视觉项目的可复用提示词结构与检查方法。","pageClass":"page-resource-detail","status":"published"},"headers":[],"relativePath":"resources/mj-prompt.md","filePath":"resources/mj-prompt.md"}'),d={name:"resources/mj-prompt.md"};function n(p,t,c,h,m,u){const e=s("MediaFrame");return o(),l("div",null,[t[0]||(t[0]=a('<h1 id="商业视觉-prompt-结构" tabindex="-1">商业视觉 Prompt 结构 <a class="header-anchor" href="#商业视觉-prompt-结构" aria-label="Permalink to &quot;商业视觉 Prompt 结构&quot;">​</a></h1><ul><li><strong>类型：</strong> 在线方法模板</li><li><strong>来源：</strong> Liuli AI Lab 自有整理</li><li><strong>授权：</strong> 署名后可用于个人与商业项目</li><li><strong>最后验证：</strong> 2026-07-11</li></ul><p>Prompt 的作用不是堆叠形容词，而是把项目目标转换为生成模型可以执行的视觉变量。</p>',3)),i(e,{src:"/aigc-3.jpg",alt:"蓝紫色数字粒子视觉，代表相互关联的提示词变量",caption:"资源预览：从任务目标、主体、场景到限制条件的 Prompt 结构。",aspect:"16 / 9"}),t[1]||(t[1]=a(`<h2 id="基础结构" tabindex="-1">基础结构 <a class="header-anchor" href="#基础结构" aria-label="Permalink to &quot;基础结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[任务目标] + [核心主体] + [使用场景] + [构图与镜头]</span></span>
<span class="line"><span>+ [光线与材质] + [色彩与品牌气质] + [必须保留的信息]</span></span>
<span class="line"><span>+ [需要避免的结果] + [输出规格]</span></span></code></pre></div><h2 id="每一部分解决什么" tabindex="-1">每一部分解决什么 <a class="header-anchor" href="#每一部分解决什么" aria-label="Permalink to &quot;每一部分解决什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>需要回答的问题</th></tr></thead><tbody><tr><td>任务目标</td><td>这张图最终服务于展示、解释、转化还是提案？</td></tr><tr><td>核心主体</td><td>产品或人物有哪些不能被改变的事实？</td></tr><tr><td>使用场景</td><td>画面会出现在哪里，由谁观看？</td></tr><tr><td>构图与镜头</td><td>信息应该先被看到什么，阅读顺序是什么？</td></tr><tr><td>光线与材质</td><td>怎样支持产品质感，而不是遮盖结构？</td></tr><tr><td>品牌气质</td><td>哪些色彩、节奏与风格必须保持一致？</td></tr><tr><td>限制条件</td><td>哪些内容不能生成、不能误导或不能出现？</td></tr></tbody></table><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ol><li>一轮只改变一到两个关键变量。</li><li>产品真实性要求高时，使用参考图并单独检查结构与标识。</li><li>保存有效条件和失败原因，不只保存最终图片。</li><li>把筛选标准写在生成之前，避免结果出来后临时改变目标。</li></ol><h2 id="关联内容" tabindex="-1">关联内容 <a class="header-anchor" href="#关联内容" aria-label="Permalink to &quot;关联内容&quot;">​</a></h2><ul><li><a href="/aigc/commercial-visual-system.html">AI 商业视觉生产系统</a></li><li><a href="/portfolio/ecommerce-visual.html">专业医疗产品电商视觉系统</a></li><li><a href="/blog/aigc-workflow-system.html">从提示词到交付：AIGC 工作流如何沉淀</a></li></ul><p><a href="/resources/">← 返回资源库</a></p>`,9))])}const g=r(d,[["render",n]]);export{b as __pageData,g as default};
